import { Ajax } from "./ajax.js";
import { Backend } from "./backend.js";
import { Caches } from "./caches.js";
import { Users } from "./users.js";

export const load_red_infiltration = () => {
    let answeringDoor = null;
    let colour = 0;
    let fadeInInterval = null;
    const logo = "                             *(%%%%%%%%%%%%%%%%#(,                             \n                       #%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%(                       \n                  ,%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%#,                  \n               #%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%/               \n            *%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%*            \n          #%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%#          \n        #%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%#        \n      /%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%/      \n     %%%%%%%#            .#%%%%%%%%%%%%%%%%%%%%%%%%%#            .#%%%%%%#     \n   ,%%%%%(                   #%%%%%%%%%%%%%%%%%%%(                   #%%%%%    \n  ,%%%%/                       #%%%%%%%%%%%%%%%/                       #%%%%,  \n .%%%%                           %%%%%%%%%%%%%                           %%%%  \n %%%%     ##,                    .%%%%%%%%%%%                     ,%#    .%%%% \n/%%%/    %%%%%%/                  /%%%%%%%%%/                  (%%%%%#    /%%%/\n%%%%    ,%%%%%%%#                  %%%%%%%%%                  #%%%%%%%,    %%%%\n%%%%    (%%%%%%%/                  %%%%%%%%%                  /%%%%%%%(    %%%%\n%%%%    *%%%%%%%#        /         %%%%%%%%%         (        #%%%%%%%*    %%%%\n%%%%*    %%%%%%%%       #%%%#     *%%%%%%%%%*    .#%%%#      *%%%%%%%#    *%%%%\n          %%%%%%%%#   .%%%%%%     %%%%%%%%%%%     %%%%%%.   #%%%%%%%%          \n           *%%%%%%%%%%%%%%%.     %%%%%%%%%%%%%     *%%%%%%%%%%%%%%%.           \n              /%%%%%%%%%/      (%%%%%%%%%%%%%%%,      /%%%%%%%%%/              \n                             /%%%%%%%%%%%%%%%%%%%,                             \n                          *%%%%%%%%%%%%%%%%%%%%%%%%%*                          \n                      %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%                      \n                        *%%%%%%%%%%%%%%%%%%%%%%%%%%%%%*                        \n                           #%%%%%%%%%%%%%%%%%%%%%%%/                           \n                              #%%%%%%%%%%%%%%%%%#                              \n                                ,%%%%%%%%%%%%%,                                \n                                   (%%%%%%%*                                   \n                                     (%%%*                                     \n                                       %                                       \n".split("\n");
    let lineCount = 0;

    const fade_to_red = muahaha => {
        colour = Math.min(1, colour + ((4.0 * 16.0) / 1000.0));
        muahaha.style.backgroundColor = `rgba(0, 0, 0, ${colour})`;
        if (colour === 1) {
            clearInterval(fadeInInterval);
        }
    };

    const update_code = code => {
        lineCount = Math.min(logo.length, lineCount + ((6.0 * 100.0) / 1000.0));
        let currentCode = "";
        for (let i = 0; i < lineCount; ++i) {
            for (let j = 0; j < logo[i].length; ++j) {
                if (logo[i][j] === " ") {
                    currentCode += logo[i][j];
                } else {
                    currentCode += String.fromCodePoint(0xEE88 + Math.floor(Math.random() * (0xEEFF - 0xEE88 + 1)));
                }
            }
            if (i < logo.length - 1) {
                currentCode += "\n";
            }
        }
        code.innerText = currentCode;
    };

    const take_over = async () => {
        await document.fonts.load("1em Commodore");

        const muahaha = document.createElement("div");
        muahaha.setAttribute("style", "z-index: 1000000; user-select: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; text-align: center;");
        const code = document.createElement("code");
        code.setAttribute("style", "display: block; position: relative; color: #ff0000; top: 50%; transform: translateY(-50%); white-space: pre; font-family: Commodore; line-height: 15pt;");
        muahaha.append(code);
        document.body.append(muahaha);
        fadeInInterval = setInterval(() => { fade_to_red(muahaha); }, 16);
        setInterval(() => { update_code(code); }, 100);
    };

    window.KnockKnock = () => {
        // Time to test if you are indeed a worthy Red Recruit!
        if (answeringDoor !== null) {
            return "Hang on!";
        }
        answeringDoor = setTimeout(() => {
            const nameAnswer = prompt("Red Penguin: \"Who's there?\"");
            answeringDoor = null;
            if (nameAnswer !== null && nameAnswer !== "") {
                Backend.getPlayerDetailsByUsername(nameAnswer, Caches.getPlayerDetailsByUsernameCache())
                    .then(result => {
                        if (typeof result === "object") {
                            if (Users.isAnyUser(result.getPlayerId())) {
                                answeringDoor = setTimeout(() => {
                                    const codeAnswer = prompt(`Red Penguin: "${nameAnswer} who?"`);
                                    answeringDoor = null;
                                    if (codeAnswer !== null && codeAnswer !== "") {
                                        answeringDoor = Ajax.request("red_infiltration", "redRecruit", [nameAnswer, codeAnswer])
                                            .then(recruitResult => {
                                                answeringDoor = null;
                                                if (recruitResult.result.result) {
                                                    alert("Red Penguin: \"Muahahahaa!\"");
                                                    take_over();
                                                } else {
                                                    alert("Red Penguin: \"Ah ah ah, you didn't say the magic word!\"");
                                                }
                                            })
                                            .catch(() => {
                                                answeringDoor = null;
                                                alert("Red Infiltration malfunction!");
                                            });
                                    } else {
                                        alert("Red Penguin: \"Red Recruits never give up!\"");
                                    }
                                }, 1000);
                            } else {
                                alert("Red Penguin: \"You don't fool me that easily!\"");
                            }
                        } else {
                            alert("Red Penguin: \"You are not who you say you are!\"");
                        }
                    })
                    .catch(() => {
                        alert("Red Infiltration malfunction!");
                    });
            } else {
                alert("Red Penguin: \"Huh, I guess nobody was there.\"");
            }
        }, 3000);
        return "...";
    };
};

let infiltrateTimeout = null;

export const reload_red_infiltration = () => {
    const infiltrate = () => {
        // My ninja haXor skills shall hide my beautiful emblem in plain sight!
        const style = document.createElement("style");
        document.querySelector("#mainContent").append(style);
        style.sheet.insertRule("@media (max-width: 1024px) { #red_infiltration {display: none; }}", 0);
        const link = document.createElement("a");
        link.id = "red_infiltration";
        link.href = "http://theredpenguin.org";
        link.target = "_blank";
        link.tabIndex = -1;
        link.setAttribute("aria-hidden", "true");
        link.setAttribute("style", "position: absolute; top: 56px; right: -135px; ");
        const resist = new Image(120, 124);
        resist.alt = "";
        resist.src = "data:image/png;base64,";
        link.appendChild(resist);
        document.querySelector("#mainContent").append(link);
    };

    clearTimeout(infiltrateTimeout);
    infiltrateTimeout = setTimeout(infiltrate, 5000);
};
